#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(svglite)})
B<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/analysis_revisions_20260906";O<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/final_analysis_20260907/Figure6_spatial_mechanistic";dir.create(O,recursive=TRUE,showWarnings=FALSE)
sp<-read.csv(file.path(B,"GSE171351_spatial_validation/GSE171351_spot_scores.csv"));ss<-read.csv(file.path(B,"GSE171351_spatial_validation/GSE171351_spatial_patient_summary.csv"));lr<-read.csv(file.path(B,"CCDC80_LR_myeloid_integration/CCDC80_LR_myeloid_integrated_ranking.csv"));tf<-read.csv(file.path(B,"CellOracle_GSE135337/CCDC80_state_target_GRN_edges.csv"))
T<-theme_classic(base_family="Arial",base_size=10)+theme(plot.title=element_text(face="bold",size=11,hjust=0),plot.subtitle=element_text(size=8,colour="#444"),axis.title=element_text(size=9),axis.text=element_text(size=8),axis.line=element_line(linewidth=.4),axis.ticks=element_line(linewidth=.3),panel.grid=element_blank(),legend.position="none",plot.margin=margin(6,12,6,12))
rep<-sp[sp$sampleID=="B1",]; rep$y<-max(rep$array_row)-rep$array_row
map<-function(d,v,t,sub,cols=c("#F2F2F2","#356A8A")){ggplot(d,aes(array_col,y,colour=.data[[v]]))+geom_point(size=1.05,alpha=.9)+scale_colour_gradientn(colours=cols)+coord_equal()+labs(title=t,subtitle=sub,x="Array column",y="Array row")+T}
pA<-ggplot(rep,aes(array_col,y))+geom_point(size=1.0,colour="#B7B7B7",alpha=.8)+coord_equal()+labs(title="(A) Representative spatial section",subtitle="GSE171351; sample B1 / Bladder8",x="Array column",y="Array row")+T
pB<-map(rep,"ECM_signature","(B) ECM program localization","CCDC80-associated ECM score")
pC<-map(rep,"Myeloid_score","(C) Myeloid niche localization","Myeloid score",c("#F2F2F2","#C98245"))
ss$lab<-paste(ss$Patient,"(n =",ss$n_spots,")");ss$lab<-factor(ss$lab,levels=rev(ss$lab));pD<-ggplot(ss,aes(rho_ECM_myeloid,lab))+geom_vline(xintercept=0,colour="#777",linewidth=.3)+geom_point(aes(size=-log10(p_ECM_myeloid)),colour="#356A8A")+labs(title="(D) Spatial ECM-myeloid association",subtitle="Patient-level Spearman correlations",x="Spearman rho",y=NULL,size="-log10 P")+T+theme(legend.position="right")
lr<-lr[order(lr$evidence_score,-lr$mean_LR_potential),];lr<-head(lr,8);lr$pair<-factor(lr$pair,levels=rev(lr$pair));pE<-ggplot(lr,aes(mean_LR_potential,pair))+geom_point(aes(size=evidence_score,colour=rho_LR_myeloid_score))+scale_x_log10()+scale_colour_gradient2(low="#B8CBD4",mid="white",high="#356A8A",midpoint=0)+labs(title="(E) Candidate CAF-myeloid axes",subtitle="LR prioritization across 7 patients; hypothesis-generating",x="Mean LR potential (log scale)",y=NULL,size="Evidence score",colour="rho")+T+theme(legend.position="right")
tf<-tf[order(-tf$abs_delta),];tf<-head(tf,8);tf$source<-factor(tf$source,levels=rev(unique(tf$source)));tf$target<-factor(tf$target,levels=rev(unique(tf$target)));tf$x1<-as.numeric(tf$source);tf$x2<-as.numeric(tf$target);tf$y1<-1;tf$y2<-2;nodes<-unique(c(as.character(tf$source),as.character(tf$target)));coords<-data.frame(node=nodes,x=match(nodes,nodes),y=ifelse(nodes%in%as.character(tf$source),1,2));pF<-ggplot(tf)+geom_segment(aes(x=x1,xend=x2,y=y1,yend=y2,linewidth=abs_delta,colour=delta_coef),alpha=.7)+geom_point(data=coords,aes(x,y),size=3,colour="#333")+geom_text(data=coords,aes(x,y,label=node),size=2.5,nudge_y=.16)+scale_colour_gradient2(low="#356A8A",mid="grey80",high="#A34B45")+scale_size_continuous(range=c(.3,1.3),guide="none")+scale_x_continuous(breaks=NULL)+scale_y_continuous(breaks=c(1,2),labels=c("TF","ECM target"),limits=c(.65,2.35))+labs(title="(F) CCDC80-state regulatory candidates",subtitle="CellOracle differential GRN edges; hypothesis-generating",x=NULL,y=NULL,colour="delta coefficient")+T
fig<-(pA|pB)/(pC|pD)/(pE|pF);ggsave(file.path(O,"Figure6_spatial_mechanistic.pdf"),fig,width=240,height=320,units="mm",device=cairo_pdf,bg="white");ggsave(file.path(O,"Figure6_spatial_mechanistic.svg"),fig,width=240,height=320,units="mm",device=svglite,bg="white");ggsave(file.path(O,"Figure6_spatial_mechanistic.tif"),fig,width=240,height=320,units="mm",dpi=600,compression="lzw",device="tiff",bg="white")
write.csv(rep,file.path(O,"Figure6_source_representative_spatial.csv"),row.names=FALSE);write.csv(ss,file.path(O,"Figure6_source_spatial_summary.csv"),row.names=FALSE);write.csv(lr,file.path(O,"Figure6_source_LR_top8.csv"),row.names=FALSE);write.csv(tf,file.path(O,"Figure6_source_CellOracle_edges.csv"),row.names=FALSE)
